data={k:[] for k in ['sources','entities','relationships','records','localities']}
def source(id,title,url,publisher,date,locator,summary,artifacts,tier='documented',limitations=None):
    data['sources'].append(dict(id=id,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt=RETRIEVED,locator=locator,summary=summary,tier=tier,limitations=(limitations or [])+['Retained evidence: '+', '.join(artifacts)]))
def geo(src,states=None,note=None,basis='project-location'):
    return [dict(scope='multi-state' if states and len(states)>1 else 'state' if states else 'national',stateCodes=states or [],localityIds=[],basis=basis if states else 'national-context',note=note or ('Project geography; not registered office or all activities of the entity.' if states else 'National institution or project-financing context; no local payment allocation inferred.'),sourceIds=src)]
def dims(src,states=None,layers=None,domains=None,limitations=None):
    return dict(sourceIds=src,geography=geo(src,states),layers=layers or ['procurement','funding'],domains=domains or ['public-works','capital','finance'],route=route,limitations=limitations or [])
def entity(id,label,type,src,summary,states=None,canonical=None,identity=None):
    d=dict(id=id,label=label,type=type,resolved=True,identityBasis=identity or 'Exact named legal entity or expressly identified project/facility in cited primary source; no contractor-string fuzzy merge.',summary=summary,**dims(src,states,['organisations']))
    if canonical:d['canonicalId']=canonical
    data['entities'].append(d)
def amount(v,stage,period,currency='INR',unit='crore'):return dict(value=v,currency=currency,unit=unit,stage=stage,period=period)
def edge(id,a,b,kind,label,src,summary,case,states=None,amts=None,start=None,end=None,status='documented-historical-transaction',asof=None,tier='documented',responses=None,alternatives=None,falsifier=None,limitations=None,dateBasis=None,layers=None,domains=None):
    data['relationships'].append(dict(id=id,from_=a,to=b,kind=kind,label=label,tier=tier,status=status,statusAsOf=asof,fromDate=start,toDate=end,dateBasis=dateBasis or ('Exact dates from the cited record.' if start or end else 'Exact event day not established; consult the stated period.'),summary=summary,alternativeExplanations=alternatives or [],falsifier=falsifier,responseIds=responses or [],recordIds=[case],amounts=amts or [],**dims(src,states,layers,domains,limitations)))
    data['relationships'][-1]['from']=data['relationships'][-1].pop('from_')
def record(id,title,summary,kind,src,entities,relationships,period,response,alternatives,falsifier,states=None,amts=None,status='bounded-source-backed-case',asof=None,start=None,end=None,tier='documented',limitations=None,layers=None,domains=None):
    data['records'].append(dict(id=id,title=title,summary=summary,kind=kind,tier=tier,status=status,statusAsOf=asof,fromDate=start,toDate=end,dateBasis='Dates are independently supported event or publication dates; month-only events remain in the period text.',entityIds=entities,relationshipIds=relationships,period=period,response=response,alternativeExplanations=alternatives,falsifier=falsifier,amounts=amts or [],**dims(src,states,layers,domains,limitations)))

