# Human-readable prose: preserve conventional spaces at boundaries in compact authoring text.
replacements={
'crore':' crore','₹ ':'₹','%of':'% of','%before':'% before','%participation':'% participation',
'Government ofIndia':'Government of India','GovernmentofIndia':'Government of India','toGovernment':'to Government',
'wholeMAHSR':'whole MAHSR','wholeproject':'whole project','C4award':'C4 award','C4contract':'C4 contract','C4agreement':'C4 agreement','C4package':'C4 package','C4scope':'C4 scope','C4price':'C4 price','C4payment':'C4 payment','C4adjudication':'C4 adjudication',
}
def clean(v):
    if isinstance(v,list):return [clean(i) for i in v]
    if isinstance(v,dict):return {k:clean(x) if k not in ['id','from','to','sourceIds','entityIds','relationshipIds','recordIds','responseIds','canonicalId','url','route','currency','unit','kind','type','status','domains','layers'] else x for k,x in v.items()}
    if isinstance(v,str):
        for a,b in replacements.items():v=v.replace(a,b)
        v=re.sub(r'(?<=[a-zA-Z])(?=\d)|(?<=\d)(?=[a-zA-Z])',' ',v)
        v=re.sub(r'\s{2,}',' ',v)
    return v
# Do not rewrite exact identifiers/dates. A prose-only pass is applied below only to display text.
textkeys={'label','title','summary','period','response','dateBasis','identityBasis','stage','note','locator','falsifier'}
def prose(v,k=None):
    if isinstance(v,list):return [prose(x,k) for x in v]
    if isinstance(v,dict):return {kk:prose(x,kk) for kk,x in v.items()}
    return clean(v) if isinstance(v,str) and (k in textkeys or k in {'limitations','alternativeExplanations'}) else v
data=prose(data)
# Final editorial pass keeps source identifiers untouched and all display prose legible.
overrides=json.loads((ROOT/'editorial_overrides.json').read_text())
for group in data.values():
    for row in group:
        if row['id'] in overrides: row.update(overrides[row['id']])
        if row['id'].startswith('nhsrcl-queue-'):
            row['falsifier']='Retrieve the original signed award or contract using the exact reference; establish legal registration, consortium membership and payment direction, then link bill, bank and completion records.'
            row['alternativeExplanations']=['A supplier label may denote a consortium or trading name. Establish exact legal identity before corporate or political joins.']
            row['limitations']=['One of 20 displayed rows, not a national or NHSRCL census.','No award amount is parsed into payment or merged with the project loan.']
        if row['id'].startswith('carry-'):
            row['summary']=row['summary'].split(' New work required:')[0]+' New work required: connect exact contract and company identities to the payment, recovery and completion chain; no such join is inferred here.'
            row['limitations']=['Carried-forward lead from the existing corpus; not counted as a newly discovered irregularity.']
